const input = items[0]?.json || {};

return [
 {
   json: {
     ...input,
     m6_config: {
       service_name: 'DALIA_M6_Handoff_Service_Lite',
       service_version: 'v1',

       contracts: {
         request_schema_version: 'dalia.to_m6.handoff_request.v1',
         result_schema_version: 'dalia.m6.handoff_result.v1'
       },

       handoff_policy: {
         enabled: true,
         default_priority: 'medium',
         max_summary_last_messages: 5,
         status_on_request: 'handoff_requested',
         status_on_human_notified: 'human_notified',

         confidence_threshold: 0.55,
         fallback_count_threshold: 2,

         allowed_reasons: [
           'human_request',
           'low_confidence',
           'technical_error',
           'complex_purchase',
           'policy_trigger',
           'commerce_failure',
           'customer_complaint'
         ],

         reason_priority_map: {
           human_request: 'medium',
           low_confidence: 'medium',
           technical_error: 'high',
           complex_purchase: 'high',
           policy_trigger: 'high',
           commerce_failure: 'high',
           customer_complaint: 'high'
         }
       },

       // 👇 AQUÍ AGREGAMOS EL NUEVO BLOQUE 👇
       summary_policy: {
         max_last_messages: 5,
         max_summary_length: 1800,
         include_session_memory: true,
         include_commerce_context: true,
         include_catalog_context: true,
         include_recommended_actions: true,
         default_recommended_action: 'Contactar al cliente, validar el contexto y continuar la atención sin pedirle repetir toda la información.',
         fallback_summary: 'Cliente requiere atención humana. Revisar el contexto disponible y continuar la conversación.'
       },
       // 👆 HASTA AQUÍ 👆
      customer_message_policy: {
 max_length: 420,
 default_text: 'Claro, te voy a conectar con una persona del equipo para que pueda ayudarte mejor. Ya le comparto el contexto para que no tengas que repetir todo.',
 fallback_text: 'Te voy a conectar con una persona del equipo para que pueda ayudarte mejor. Ya le comparto el contexto de la conversación.',
 ask_closing_question: false,
 avoid_terms: [
   'handoff',
   'workflow',
   'n8n',
   'módulo',
   'modulo',
   'error técnico',
   'herramienta',
   'sistema falló',
   'fallo interno',
   'escalamiento técnico'
 ],
 templates_by_reason: {
   human_request: 'Claro, te voy a conectar con una persona del equipo para que pueda ayudarte mejor. Ya le comparto el contexto para que no tengas que repetir todo.',
   low_confidence: 'Para ayudarte mejor, voy a compartir tu caso con una persona del equipo. Así podrá continuar con el contexto de lo que ya hablamos.',
   technical_error: 'Voy a pedir apoyo de una persona del equipo para revisar tu caso con más detalle. Le compartiré el contexto para que pueda ayudarte sin que tengas que repetir todo.',
   complex_purchase: 'Para acompañarte mejor en esta compra, voy a conectar tu caso con una persona del equipo. Ya le comparto el contexto para que pueda continuar desde aquí.',
   commerce_failure: 'Voy a compartir tu caso con una persona del equipo para que pueda ayudarte a continuar con la compra. Le enviaré el contexto de lo que ya revisamos.',
   customer_complaint: 'Entiendo. Voy a compartir tu caso con una persona del equipo para que pueda revisarlo con más cuidado y continuar la atención.'
 }
},

       human_channels: {
         whatsapp: {
           enabled: true,
           to: '573192563967'
         },
         telegram: {
           enabled: true,
           chat_id: '5826865485'
         }
       },

       customer_message_policy: {
         default_text: 'Claro, te voy a conectar con una persona del equipo para que pueda ayudarte mejor. Ya le comparto el contexto para que no tengas que repetir todo.',
         avoid_terms: [
           'handoff',
           'workflow',
           'n8n',
           'módulo',
           'modulo',
           'error técnico',
           'herramienta'
         ]
       }
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function safeNumber(value, fallback = 0) {
 const n = Number(value);
 return Number.isFinite(n) ? n : fallback;
}

const input = items[0]?.json || {};
const config = input.m6_config || {};

const trace = input.trace || {};
const context = input.context || {};
const currentInput = input.input || {};
const decision = input.decision || {};
const handoff = input.handoff || {};

const sessionMemory = input.session_memory || {};
const commerce = input.commerce || {};
const catalog = input.catalog || {};

const normalizedReason =
 clean(handoff.reason) ||
 clean(decision.handoff?.reason) ||
 clean(decision.reason) ||
 'human_request';

const priorityFromMap =
 config.handoff_policy?.reason_priority_map?.[normalizedReason];

const normalizedPriority =
 clean(handoff.priority) ||
 clean(priorityFromMap) ||
 config.handoff_policy?.default_priority ||
 'medium';

const softCustomerContext = input.soft_customer_context || {
  has_relevant_memory: false,
  memory_confidence: 'none',
  safe_summary: null,
  conversation_cues: [],
  do_not_say: []
};
const customerVectorMemory = input.customer_vector_memory || {
  retrieved: false,
  usable: false,
  memories: []
};

const m6Request = {
 schema_version:
   input.schema_version ||
   config.contracts?.request_schema_version ||
   'dalia.to_m6.handoff_request.v1',

 operation: clean(input.operation || 'request_handoff'),

 trace: {
   event_id: clean(trace.event_id),
   conversation_id: clean(trace.conversation_id),
   session_id: clean(trace.session_id)
 },

 context: {
   environment: clean(context.environment || 'demo'),
   business_id: clean(context.business_id || 'business_demo'),
   channel: clean(context.channel || 'whatsapp'),
   user_id: clean(context.user_id),
   display_name: clean(context.display_name)
 },

 input: {
   message_id: clean(currentInput.message_id),
   type: clean(currentInput.type || 'text'),
   text: clean(currentInput.text),
   timestamp: clean(currentInput.timestamp)
 },

 decision: {
   intent: clean(decision.intent),
   route: clean(decision.route || 'handoff'),
   confidence: safeNumber(decision.confidence, 0),
   commercial_stage: clean(decision.commercial_stage),
   reason: clean(decision.reason)
 },

 handoff: {
   required: handoff.required !== false,
   reason: normalizedReason,
   priority: normalizedPriority,
   triggered_by: clean(handoff.triggered_by || 'coordinator'),
   requested_by_module: clean(handoff.requested_by_module || 'M2')
 },

 session_memory: sessionMemory,
 commerce,
 catalog
};

return [
 {
   json: {
     ...input,
     m6_request: m6Request,
     soft_customer_context: softCustomerContext,
     customer_vector_memory: customerVectorMemory
   }
 }
];

function isEmpty(value) {
 return value === null || value === undefined || String(value).trim() === '';
}

const input = items[0]?.json || {};
const request = input.m6_request || {};
const config = input.m6_config || {};

const errors = [];
const warnings = [];

if (request.operation !== 'request_handoff') {
 errors.push('unsupported_operation');
}

if (isEmpty(request.context?.user_id)) {
 errors.push('missing_user_id');
}

if (isEmpty(request.trace?.session_id)) {
 warnings.push('missing_session_id');
}

if (isEmpty(request.input?.text)) {
 warnings.push('missing_user_text');
}

if (request.decision?.route !== 'handoff') {
 warnings.push('route_is_not_handoff');
}

if (!request.handoff?.required) {
 warnings.push('handoff_not_marked_as_required');
}

const allowedReasons = config.handoff_policy?.allowed_reasons || [];

if (!allowedReasons.includes(request.handoff?.reason)) {
 warnings.push('handoff_reason_not_in_allowed_list');
}

return [
 {
   json: {
     ...input,
     m6_validation: {
       valid: errors.length === 0,
       errors,
       warnings
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function normalize(value) {
 return clean(value)
   .toLowerCase()
   .normalize('NFD')
   .replace(/[\u0300-\u036f]/g, '');
}

function includesAny(text, signals) {
 const value = normalize(text);
 return signals.some(signal => value.includes(normalize(signal)));
}

const input = items[0]?.json || {};
const config = input.m6_config || {};
const request = input.m6_request || {};
const validation = input.m6_validation || {};

const policy = config.handoff_policy || {};
const userText = request.input?.text || '';

const explicitHumanSignals = [
 'asesor',
 'humano',
 'persona',
 'vendedor',
 'llamada',
 'llamar',
 'alguien',
 'hablar con alguien',
 'hablar con una persona',
 'atencion humana',
 'atención humana'
];

const technicalSignals = [
 'error',
 'fallo',
 'no funciona',
 'problema',
 'no carga',
 'no puedo pagar',
 'no me deja'
];

let eligible = false;
let reason = clean(request.handoff?.reason);
let priority = clean(request.handoff?.priority || policy.default_priority || 'medium');
let triggeredBy = clean(request.handoff?.triggered_by);

const confidence = Number(request.decision?.confidence || 0);

const explicitHumanRequest =
 request.decision?.intent === 'human_request' ||
 includesAny(userText, explicitHumanSignals);

const lowConfidence =
 request.decision?.intent === 'unknown' ||
 confidence < Number(policy.confidence_threshold || 0.55);

const technicalIssue =
 reason === 'technical_error' ||
 includesAny(userText, technicalSignals);

if (!validation.valid) {
 eligible = false;
 reason = reason || 'invalid_request';
} else if (request.handoff?.required === true) {
 eligible = true;
} else if (explicitHumanRequest) {
 eligible = true;
 reason = 'human_request';
 triggeredBy = 'explicit_user_request';
} else if (lowConfidence) {
 eligible = true;
 reason = 'low_confidence';
 triggeredBy = 'low_confidence_or_unknown_intent';
} else if (technicalIssue) {
 eligible = true;
 reason = 'technical_error';
 triggeredBy = 'technical_issue_detected';
}

if (!reason || !policy.allowed_reasons?.includes(reason)) {
 if (explicitHumanRequest) reason = 'human_request';
 else if (lowConfidence) reason = 'low_confidence';
 else if (technicalIssue) reason = 'technical_error';
 else reason = 'human_request';
}

priority =
 policy.reason_priority_map?.[reason] ||
 priority ||
 policy.default_priority ||
 'medium';

return [
 {
   json: {
     ...input,
     handoff_evaluation: {
       eligible,
       reason,
       priority,
       triggered_by: triggeredBy || 'criteria_engine',
       confidence,
       explicit_human_request: explicitHumanRequest,
       low_confidence: lowConfidence,
       technical_issue: technicalIssue,
       evaluated_at: new Date().toISOString()
     }
   }
 }
];

const input = items[0]?.json || {};
const request = input.m6_request || {};

return [
 {
   json: {
     schema_version: 'dalia.m6.handoff_result.v1',
     success: false,
     result_type: 'handoff_not_eligible',

     handoff: {
       handoff_id: '',
       status: 'not_requested',
       reason: input.handoff_evaluation?.reason || '',
       priority: input.handoff_evaluation?.priority || 'medium',
       eligible: false
     },

     m7_output: {
       schema_version: 'dalia.m6_to_m7.v1',
       trace: request.trace || {},
       channel: {
         name: request.context?.channel || 'whatsapp',
         user_id: request.context?.user_id || '',
         display_name: request.context?.display_name || ''
       },
       message: {
         replyText: 'Puedo seguir ayudándote por aquí. ¿Qué necesitas revisar?',
         response_type: 'handoff_not_required',
         next_step: 'continue_ai_conversation'
       },
       presentation: {
         sendImage: false,
         image_mode: 'none',
         image_candidates: []
       },
       control: {
         can_continue: true,
         fallback_reason: 'handoff_not_eligible'
       }
     },

     validation: input.m6_validation || {},
     evaluation: input.handoff_evaluation || {}
   }
 }
];

const input = items[0]?.json || {};
const request = input.m6_request || {};
const evaluation = input.handoff_evaluation || {};

return [
 {
   json: {
     ...input,
     handoff_context: {
       ready: true,
       reason: evaluation.reason || request.handoff?.reason || 'human_request',
       priority: evaluation.priority || request.handoff?.priority || 'medium',
       triggered_by: evaluation.triggered_by || request.handoff?.triggered_by || 'criteria_engine',
       requested_by_module: request.handoff?.requested_by_module || 'M2',
       status_on_request:
         input.m6_config?.handoff_policy?.status_on_request ||
         'handoff_requested',
       next_step: 'build_handoff_package'
     },
     branch_context: {
       branch: 'handoff_eligible',
       configured_in_task: 1,
       next_task: 2,
       status: 'criteria_ready'
     }
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function makeId(prefix) {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
 return `${prefix}_${ts}_${rand}`;
}

function ensureArray(value) {
 if (Array.isArray(value)) return value;
 if (!value) return [];

 if (typeof value === 'string') {
   try {
     const parsed = JSON.parse(value);
     return Array.isArray(parsed) ? parsed : [];
   } catch (e) {
     return [];
   }
 }

 return [];
}

function firstNonEmpty(...values) {
 for (const value of values) {
   const cleaned = clean(value);
   if (cleaned) return cleaned;
 }
 return '';
}

function compactProduct(product = {}) {
 return {
   product_id: clean(product.product_id || product.sku),
   sku: clean(product.sku || product.product_id),
   display_name: clean(product.display_name || product.product_name || product.name),
   category: clean(product.category),
   quantity: product.quantity || null,
   amount: product.amount || null,
   currency: clean(product.currency)
 };
}

function getProductsFromMemory(sessionMemory) {
 const commercial = sessionMemory?.commercial_context || {};
 const reference = sessionMemory?.reference_context || {};

 const products = [];

 if (commercial.last_product_consulted) {
   products.push({
     display_name: commercial.last_product_consulted,
     category: commercial.last_category_consulted || ''
   });
 }

 if (Array.isArray(commercial.last_products_recommended)) {
   products.push(...commercial.last_products_recommended);
 }

 if (reference.current_focus_product) {
   products.push({
     display_name: reference.current_focus_product
   });
 }

 if (Array.isArray(reference.current_focus_products)) {
   products.push(...reference.current_focus_products);
 }

 const seen = new Set();

 return products
   .map(compactProduct)
   .filter(product => product.display_name || product.product_id)
   .filter(product => {
     const key = `${product.product_id}|${product.display_name}`.toLowerCase();
     if (seen.has(key)) return false;
     seen.add(key);
     return true;
   })
   .slice(0, 5);
}

function getLastMessages(sessionMemory, currentText, maxMessages = 5) {
 const recentTurns = ensureArray(sessionMemory?.recent_turns);

 const messages = recentTurns.map(turn => ({
   at: clean(turn.at || turn.timestamp),
   user_message: clean(turn.user_message || turn.message || turn.content),
   intent: clean(turn.intent),
   response_type: clean(turn.response_type),
   product_consulted: clean(turn.product_consulted)
 }));

 if (currentText) {
   messages.push({
     at: new Date().toISOString(),
     user_message: currentText,
     intent: '',
     response_type: '',
     product_consulted: ''
   });
 }

 return messages
   .filter(message => message.user_message)
   .slice(-maxMessages);
}

const input = items[0]?.json || {};

const config = input.m6_config || {};
const request = input.m6_request || {};
const evaluation = input.handoff_evaluation || {};
const handoffContext = input.handoff_context || {};

const sessionMemory = request.session_memory || {};
const commerce = request.commerce || {};
const catalog = request.catalog || {};

const summaryPolicy = config.summary_policy || {};

const handoffId = makeId('hnd_demo');

const memoryCommercial = sessionMemory.commercial_context || {};
const memoryReference = sessionMemory.reference_context || {};

const catalogItems = ensureArray(catalog.items).map(compactProduct);

const memoryProducts = getProductsFromMemory(sessionMemory);

const commerceProduct = compactProduct({
 product_id: commerce.product_id || commerce.sku || commerce.commerce?.product_id,
 sku: commerce.sku || commerce.commerce?.sku,
 product_name: commerce.product_name || commerce.commerce?.product_name,
 category: commerce.category || commerce.commerce?.category,
 quantity: commerce.quantity || commerce.commerce?.quantity,
 amount: commerce.amount || commerce.commerce?.amount,
 currency: commerce.currency || commerce.commerce?.currency
});

const relatedProducts = [
 commerceProduct,
 ...catalogItems,
 ...memoryProducts
].filter(product => product.display_name || product.product_id);

const seenProducts = new Set();
const uniqueRelatedProducts = relatedProducts.filter(product => {
 const key = `${product.product_id}|${product.display_name}`.toLowerCase();
 if (seenProducts.has(key)) return false;
 seenProducts.add(key);
 return true;
}).slice(0, 5);

const currentUserText = clean(request.input?.text);

const lastMessages = getLastMessages(
 sessionMemory,
 currentUserText,
 summaryPolicy.max_last_messages || 5
);

const transactionId = firstNonEmpty(
 commerce.transaction_id,
 commerce.commerce?.transaction_id,
 commerce.transaction?.transaction_id
);

const transactionStatus = firstNonEmpty(
 commerce.status,
 commerce.commerce?.status,
 commerce.transaction?.status
);

const customerCity = firstNonEmpty(
 commerce.customer_city,
 commerce.customer?.city,
 memoryCommercial.last_city_detected
);

const customerName = firstNonEmpty(
 request.context?.display_name,
 commerce.customer_name,
 commerce.customer?.name,
 sessionMemory.identity?.display_name
);

const reason = handoffContext.reason || evaluation.reason || request.handoff?.reason || 'human_request';
const priority = handoffContext.priority || evaluation.priority || request.handoff?.priority || 'medium';

const alerts = [];

if (reason === 'technical_error') {
 alerts.push('Revisar posible error técnico reportado durante la conversación.');
}

if (reason === 'low_confidence') {
 alerts.push('La IA no tuvo suficiente confianza para continuar sin apoyo humano.');
}

if (reason === 'complex_purchase' || reason === 'commerce_failure') {
 alerts.push('Caso comercial requiere validación humana antes de continuar.');
}

if (transactionStatus) {
 alerts.push(`Existe contexto transaccional en estado: ${transactionStatus}.`);
}

const recommendedActions = [];

if (reason === 'human_request') {
 recommendedActions.push('Responder al cliente indicando que ya se tiene el contexto y continuar la atención.');
}

if (uniqueRelatedProducts.length > 0) {
 recommendedActions.push('Validar el producto de interés y confirmar disponibilidad o siguiente paso comercial.');
}

if (transactionId) {
 recommendedActions.push('Revisar la transacción asociada antes de proponer cierre o pago.');
}

if (recommendedActions.length === 0) {
 recommendedActions.push(
   summaryPolicy.default_recommended_action ||
   'Contactar al cliente, validar el contexto y continuar la atención.'
 );
}

const conversationSummaryParts = [];

if (reason === 'human_request') {
 conversationSummaryParts.push('El cliente solicitó atención humana.');
} else if (reason === 'low_confidence') {
 conversationSummaryParts.push('La conversación fue escalada por baja confianza o intención no resuelta.');
} else if (reason === 'technical_error') {
 conversationSummaryParts.push('La conversación fue escalada por posible error técnico o funcional.');
} else if (reason === 'complex_purchase') {
 conversationSummaryParts.push('La conversación fue escalada por una compra o cierre comercial complejo.');
} else {
 conversationSummaryParts.push('La conversación requiere intervención humana.');
}

if (currentUserText) {
 conversationSummaryParts.push(`Último mensaje del cliente: "${currentUserText}".`);
}

if (uniqueRelatedProducts.length > 0) {
 conversationSummaryParts.push(
   `Producto(s) relacionado(s): ${uniqueRelatedProducts.map(p => p.display_name || p.product_id).join(', ')}.`
 );
}

if (transactionId) {
 conversationSummaryParts.push(
   `Transacción relacionada: ${transactionId}, estado: ${transactionStatus || 'sin estado disponible'}.`
 );
}

const conversationSummary = conversationSummaryParts.join(' ');

const handoffPackage = {
 handoff_id: handoffId,

 status: handoffContext.status_on_request || 'handoff_requested',
 reason,
 priority,
 triggered_by: handoffContext.triggered_by || request.handoff?.triggered_by || '',
 requested_by_module: handoffContext.requested_by_module || request.handoff?.requested_by_module || 'M2',

 trace: request.trace || {},

 customer_profile: {
   user_id: request.context?.user_id || '',
   display_name: customerName || '',
   channel: request.context?.channel || 'whatsapp',
   city: customerCity || ''
 },

 conversation_context: {
   summary: conversationSummary,
   last_user_message: currentUserText,
   last_messages: lastMessages,
   intent: request.decision?.intent || '',
   confidence: request.decision?.confidence || 0,
   commercial_stage: request.decision?.commercial_stage || ''
 },

 commercial_context: {
   products: uniqueRelatedProducts,
   last_product_consulted: memoryCommercial.last_product_consulted || '',
   last_preference_detected: memoryCommercial.last_preference_detected || '',
   last_category_consulted: memoryCommercial.last_category_consulted || '',
   current_focus_product: memoryReference.current_focus_product || '',
   recommended_next_action: recommendedActions[0] || ''
 },

 transaction_context: {
   transaction_id: transactionId || '',
   status: transactionStatus || '',
   amount: commerce.amount || commerce.commerce?.amount || null,
   currency: commerce.currency || commerce.commerce?.currency || ''
 },

 alerts,
 recommended_actions: recommendedActions,

 metadata: {
   demo_mode: true,
   source_module: 'M6',
   created_at: new Date().toISOString()
 }
};

return [
 {
   json: {
     ...input,
     correlation: {
       ...(input.correlation || request.correlation || {}),
       handoff_id: handoffId
     },
     handoff_package: handoffPackage
   }
 }
];

function clean(value) {
 if (value === null || value === undefined) return '';
 return String(value).trim();
}

function safeJoin(values, separator = '\n') {
 return values.filter(Boolean).join(separator);
}

function formatProduct(product) {
 const name = clean(product.display_name || product.product_name || product.product_id);
 const category = clean(product.category);
 const qty = product.quantity ? ` | Cantidad: ${product.quantity}` : '';
 const amount = product.amount ? ` | Valor: ${product.amount} ${product.currency || ''}` : '';

 if (!name) return '';

 return `- ${name}${category ? ` | Categoría: ${category}` : ''}${qty}${amount}`;
}

const input = items[0]?.json || {};
const pkg = input.handoff_package || {};
const config = input.m6_config || {};
const policy = config.summary_policy || {};

const customer = pkg.customer_profile || {};
const conversation = pkg.conversation_context || {};
const commercial = pkg.commercial_context || {};
const transaction = pkg.transaction_context || {};

const products = Array.isArray(commercial.products)
 ? commercial.products
 : [];

const lastMessages = Array.isArray(conversation.last_messages)
 ? conversation.last_messages
 : [];

const alerts = Array.isArray(pkg.alerts)
 ? pkg.alerts
 : [];

const recommendedActions = Array.isArray(pkg.recommended_actions)
 ? pkg.recommended_actions
 : [];

const productBlock = products.length > 0
 ? products.map(formatProduct).filter(Boolean).join('\n')
 : '- Sin producto específico identificado.';

const lastMessagesBlock = lastMessages.length > 0
 ? lastMessages.map((message, index) => {
     const text = clean(message.user_message);
     return `${index + 1}. ${text}`;
   }).join('\n')
 : '- Sin mensajes recientes disponibles.';

const alertsBlock = alerts.length > 0
 ? alerts.map(alert => `- ${alert}`).join('\n')
 : '- Sin alertas adicionales.';

const recommendedActionsBlock = recommendedActions.length > 0
 ? recommendedActions.map(action => `- ${action}`).join('\n')
 : `- ${policy.default_recommended_action || 'Contactar al cliente y continuar la atención.'}`;

const transactionBlock = transaction.transaction_id
 ? safeJoin([
     `ID: ${transaction.transaction_id}`,
     `Estado: ${transaction.status || 'sin estado disponible'}`,
     transaction.amount ? `Valor: ${transaction.amount} ${transaction.currency || ''}` : ''
   ], '\n')
 : 'Sin transacción asociada.';

let humanSummary = safeJoin([
 '🔔 HANDOFF DALIA',
 '',
 `ID handoff: ${pkg.handoff_id || ''}`,
 `Motivo: ${pkg.reason || 'human_request'}`,
 `Prioridad: ${pkg.priority || 'medium'}`,
