function removeForbiddenTerms(text, forbiddenTerms = []) {
 let result = clean(text);

 for (const term of forbiddenTerms) {
   if (!term) continue;

   const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
   const regex = new RegExp(escaped, 'gi');
   result = result.replace(regex, '');
 }

 return result
   .replace(/\s{2,}/g, ' ')
   .replace(/\s+([.,;:!?])/g, '$1')
   .trim();
}

