function buildVectorMemoryBlock(vectorMemory) {
  if (!vectorMemory?.usable || !vectorMemory?.memories?.length) return '';

  const lines = vectorMemory.memories
    .filter(m => m.memory_text && m.score >= 0.65)
    .map(m => {
      const pct = Math.round((m.score || 0) * 100);
      if (m.memory_type === 'product_interest' && m.product_name) {
        return `• Producto consultado antes: ${m.product_name} (${pct}% relevancia)`;
      }
      if (m.memory_type === 'purchase_context' && m.product_name) {
        return `• Compra iniciada antes: ${m.product_name} (${pct}% relevancia) — pendiente de confirmar`;
      }
      if (m.memory_type === 'city_or_location' && m.city) {
        return `• Ciudad mencionada antes: ${m.city} (${pct}% relevancia) — pendiente de confirmar`;
      }
      if (m.memory_type === 'preference') {
        return `• Preferencia detectada: ${m.memory_text.substring(0, 100)} (${pct}% relevancia)`;
      }
      if (m.memory_type === 'handoff_context') {
        return `• Ya solicitó agente humano anteriormente (${pct}% relevancia)`;
      }
      return `• ${m.memory_text.substring(0, 100)} (${pct}% relevancia)`;
    });

  if (!lines.length) return '';

  return (
    `\n\n📋 Contexto histórico del cliente\n` +
    `(conversaciones anteriores — pendiente de confirmar con el cliente)\n` +
    lines.join('\n')
  );
}

